#!/usr/bin/env python3
from pathlib import Path
import argparse, shutil, tempfile

REL = {
 'frame':'app/src/main/java/com/particlesdevs/photoncamera/processing/ImageFrame.java',
 'batch':'app/src/main/java/com/particlesdevs/photoncamera/processing/IrisNightBatch.java',
 'selector':'app/src/main/java/com/particlesdevs/photoncamera/processing/parameters/IrisNightFrameSelector.java',
 'exposure':'app/src/main/java/com/particlesdevs/photoncamera/processing/parameters/IrisNightExposureSelector.java',
 'processor':'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/IrisNightProcessor.java',
 'bridge':'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/PhotonMotionMgc1271Bridge.kt',
 'highlight_java':'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2HighlightChromaReliability.java',
 'highlight_shader':'app/src/main/assets/shaders/motionv2/highlight_chroma_reliability.glsl',
 'capture':'app/src/main/java/com/particlesdevs/photoncamera/capture/CaptureController.java',
 'version':'app/version.properties',
}

def once(s, old, new, label):
    n=s.count(old)
    if n!=1: raise RuntimeError(f'{label}: expected 1 anchor, found {n}')
    return s.replace(old,new,1)

def write(root,key,text):
    (root/REL[key]).write_text(text)

def transform(root: Path):
    # Exact baseline/version guard.
    v=(root/REL['version']).read_text()
    if 'VERSION_NAME=0.9726540' not in v or 'VERSION_BUILD=26540' not in v:
        raise RuntimeError('not exact 26540 V1.1 version baseline')

    # Add the Night-only shadow-long semantic role without changing existing Motion roles.
    p=root/REL['frame']; s=p.read_text()
    s=once(s,
      'public enum MotionV2FrameRole { NORMAL, HIGHLIGHT_SHORT }',
      'public enum MotionV2FrameRole { NORMAL, HIGHLIGHT_SHORT, SHADOW_LONG }',
      'ImageFrame role enum')
    p.write_text(s)

    write(root,'selector','''package com.particlesdevs.photoncamera.processing.parameters;\n\n/** IRIS_26541_NIGHT_12_PLUS_3_FRAME_OWNER\n * Dedicated Night is a fixed fresh post-shutter bracket: twelve short/reference-cohort RAWs plus\n * three longer shadow RAWs. It is intentionally independent of the Motion ZSL frame slider/ring.\n */\npublic final class IrisNightFrameSelector {\n    public static final int SHORT_FRAMES = 12;\n    public static final int LONG_FRAMES = 3;\n    public static final int TOTAL_FRAMES = SHORT_FRAMES + LONG_FRAMES;\n    private IrisNightFrameSelector() {}\n    public static int getFrames(int requestedMaximum) {\n        return TOTAL_FRAMES;\n    }\n}\n''')

    write(root,'exposure','''package com.particlesdevs.photoncamera.processing.parameters;\n\nimport android.hardware.camera2.CameraCharacteristics;\nimport android.hardware.camera2.CaptureRequest;\nimport android.hardware.camera2.CaptureResult;\nimport android.util.Range;\n\nimport com.particlesdevs.photoncamera.capture.CaptureController;\nimport com.particlesdevs.photoncamera.util.Log;\n\n/** IRIS_26541_NIGHT_12_PLUS_3_EXPOSURE_SOLE_OWNER\n * Two Night exposure classes are frozen once at shutter time. The 12 short frames preserve the\n * proven 26540 highlight/motion-safe target and own geometry. The 3 long frames keep the same ISO\n * and add real integration time for shadow SNR, adaptively bounded by shake and sensor limits.\n * No Photon IsoExpoSelector, Motion ZSL state, or pre-shutter RAW participates.\n */\npublic final class IrisNightExposureSelector {\n    private static final String TAG = "IrisNightExposure";\n    private static final double LONG_TARGET_MULTIPLIER = 4.0; // +2 EV nominal; capped adaptively.\n\n    public static final class Plan {\n        // Compatibility aliases: the reference/short cohort remains the primary Night exposure.\n        public final long exposureNs;\n        public final int iso;\n        public final long shortExposureNs;\n        public final int shortIso;\n        public final long longExposureNs;\n        public final int longIso;\n        public final double longToShortEnergyRatio;\n        public final long exposureLowNs;\n        public final long exposureHighNs;\n        public final int isoLow;\n        public final int isoHigh;\n        public final int analogIso;\n        public final boolean tripod;\n        public final int shakiness;\n        public final int antibandingMode;\n\n        Plan(long shortExposureNs, int shortIso, long longExposureNs, int longIso,\n             long exposureLowNs, long exposureHighNs, int isoLow, int isoHigh, int analogIso,\n             boolean tripod, int shakiness, int antibandingMode) {\n            this.exposureNs = shortExposureNs;\n            this.iso = shortIso;\n            this.shortExposureNs = shortExposureNs;\n            this.shortIso = shortIso;\n            this.longExposureNs = longExposureNs;\n            this.longIso = longIso;\n            this.longToShortEnergyRatio =\n                    (longExposureNs * (double) longIso) /\n                    Math.max(1.0, shortExposureNs * (double) shortIso);\n            this.exposureLowNs = exposureLowNs;\n            this.exposureHighNs = exposureHighNs;\n            this.isoLow = isoLow;\n            this.isoHigh = isoHigh;\n            this.analogIso = analogIso;\n            this.tripod = tripod;\n            this.shakiness = shakiness;\n            this.antibandingMode = antibandingMode;\n        }\n    }\n\n    private IrisNightExposureSelector() {}\n\n    private static long clamp(long v, long lo, long hi) {\n        return Math.max(lo, Math.min(hi, v));\n    }\n\n    // Exact 26540 short/reference motion cap.\n    private static long shortMotionCap(boolean tripod, int shakiness, long sensorHigh) {\n        if (tripod) return Math.min(sensorHigh, ExposureIndex.sec * 2L);\n        if (shakiness <= 30) return Math.min(sensorHigh, ExposureIndex.sec / 4L);\n        if (shakiness <= 70) return Math.min(sensorHigh, ExposureIndex.sec / 8L);\n        if (shakiness <= 150) return Math.min(sensorHigh, ExposureIndex.sec / 15L);\n        return Math.min(sensorHigh, ExposureIndex.sec / 30L);\n    }\n\n    // Long frames are deliberately allowed more integration, but shake still bounds them.\n    private static long longMotionCap(boolean tripod, int shakiness, long sensorHigh) {\n        if (tripod) return Math.min(sensorHigh, ExposureIndex.sec * 8L);\n        if (shakiness <= 30) return Math.min(sensorHigh, ExposureIndex.sec);\n        if (shakiness <= 70) return Math.min(sensorHigh, ExposureIndex.sec / 2L);\n        if (shakiness <= 150) return Math.min(sensorHigh, ExposureIndex.sec / 4L);\n        return Math.min(sensorHigh, ExposureIndex.sec / 8L);\n    }\n\n    private static long antiFlicker(long desired, long cap, int antibandingMode) {\n        long q = antibandingMode == CaptureResult.CONTROL_AE_ANTIBANDING_MODE_50HZ\n                ? ExposureIndex.sec / 100L : ExposureIndex.sec / 120L;\n        desired = Math.min(desired, cap);\n        if (desired < q) return desired;\n        long n = Math.max(1L, Math.round((double) desired / q));\n        while (n * q > cap && n > 1L) n--;\n        return n * q;\n    }\n\n    public static Plan freezePlan(CaptureController controller,\n                                  CameraCharacteristics characteristics,\n                                  float exposureCompensationEv,\n                                  boolean tripod,\n                                  int shakiness,\n                                  CaptureResult previewResult) {\n        Range<Long> exposureRange = characteristics == null ? null\n                : characteristics.get(CameraCharacteristics.SENSOR_INFO_EXPOSURE_TIME_RANGE);\n        Range<Integer> isoRange = characteristics == null ? null\n                : characteristics.get(CameraCharacteristics.SENSOR_INFO_SENSITIVITY_RANGE);\n        Integer analogObj = characteristics == null ? null\n                : characteristics.get(CameraCharacteristics.SENSOR_MAX_ANALOG_SENSITIVITY);\n        long exposureLow = exposureRange == null ? ExposureIndex.sec / 1000L : exposureRange.getLower();\n        long exposureHigh = exposureRange == null ? ExposureIndex.sec : exposureRange.getUpper();\n        int isoLow = isoRange == null ? 100 : isoRange.getLower();\n        int isoHigh = isoRange == null ? 3200 : isoRange.getUpper();\n        int analogIso = analogObj == null ? 100 : analogObj;\n        Integer ab = previewResult == null ? null\n                : previewResult.get(CaptureResult.CONTROL_AE_ANTIBANDING_MODE);\n        int antibanding = ab == null ? CaptureResult.CONTROL_AE_ANTIBANDING_MODE_AUTO : ab;\n        int safeShakiness = Math.max(0, shakiness);\n\n        double compensation = Math.pow(2.0, exposureCompensationEv);\n        // Preserve 26540/26533's -0.70 EV highlight-protection target for the short/reference cohort.\n        double meteredEnergy = Math.max(1.0,\n                controller.mPreviewExposureTime * (double) Math.max(1, controller.mPreviewIso));\n        double targetEnergy = meteredEnergy * compensation / Math.pow(2.0, 0.70);\n        long shortCap = shortMotionCap(tripod, safeShakiness, exposureHigh);\n        long shortDesired = (long) Math.round(targetEnergy / Math.max(100, isoLow));\n        long shortExposure = clamp(\n                antiFlicker(clamp(shortDesired, exposureLow, shortCap), shortCap, antibanding),\n                exposureLow, exposureHigh);\n        int shortIso = (int) Math.round(targetEnergy / Math.max(1.0, shortExposure));\n        shortIso = Math.max(isoLow, Math.min(isoHigh, shortIso));\n\n        double manualExposure = controller.getParamController().getCurrentExposureValue();\n        double manualIso = controller.getParamController().getCurrentISOValue();\n        if (manualExposure != 0.0)\n            shortExposure = clamp((long) manualExposure, exposureLow, exposureHigh);\n        if (manualIso != 0.0)\n            shortIso = Math.max(isoLow, Math.min(isoHigh, (int) manualIso));\n\n        long longCap = Math.max(shortExposure, longMotionCap(tripod, safeShakiness, exposureHigh));\n        long desiredLong = (long) Math.ceil(shortExposure * LONG_TARGET_MULTIPLIER);\n        long longExposure = clamp(\n                antiFlicker(clamp(desiredLong, exposureLow, longCap), longCap, antibanding),\n                exposureLow, exposureHigh);\n        int longIso = shortIso; // integration time, not ISO amplification, provides the extra photons.\n        if (longExposure <= shortExposure) {\n            // Try the smallest physically longer exposure if anti-flicker quantization collapsed it.\n            long oneStep = Math.min(exposureHigh, shortExposure + Math.max(1L, exposureLow));\n            if (oneStep > shortExposure && oneStep <= longCap) longExposure = oneStep;\n        }\n        if (longExposure <= shortExposure) {\n            throw new IllegalStateException(\n                    "26541 Night cannot form a physically longer shadow exposure: short="\n                            + shortExposure + " sensorHigh=" + exposureHigh + " longCap=" + longCap);\n        }\n\n        Plan plan = new Plan(shortExposure, shortIso, longExposure, longIso,\n                exposureLow, exposureHigh, isoLow, isoHigh, analogIso, tripod, safeShakiness, antibanding);\n        Log.i(TAG, "IRIS_26541_NIGHT_12_PLUS_3_EXPOSURE"\n                + " shortNs=" + plan.shortExposureNs + " shortIso=" + plan.shortIso\n                + " longNs=" + plan.longExposureNs + " longIso=" + plan.longIso\n                + " longToShortEnergy=" + plan.longToShortEnergyRatio\n                + " shortCapNs=" + shortCap + " longCapNs=" + longCap\n                + " tripod=" + tripod + " shakiness=" + safeShakiness\n                + " freshPostShutter=true zsl=false photonIsoExpoSelector=false planFrozenAtShutter=true");\n        return plan;\n    }\n\n    private static void apply(CaptureRequest.Builder builder, long exposureNs, int iso, String label) {\n        if (builder == null) throw new IllegalArgumentException("26541 Night " + label + " builder is null");\n        builder.set(CaptureRequest.CONTROL_AE_MODE, CaptureRequest.CONTROL_AE_MODE_OFF);\n        builder.set(CaptureRequest.SENSOR_EXPOSURE_TIME, exposureNs);\n        builder.set(CaptureRequest.SENSOR_SENSITIVITY, iso);\n    }\n\n    public static void applyShortPlan(CaptureRequest.Builder builder, Plan plan) {\n        if (plan == null) throw new IllegalArgumentException("26541 Night exposure plan is null");\n        apply(builder, plan.shortExposureNs, plan.shortIso, "short");\n    }\n\n    public static void applyLongPlan(CaptureRequest.Builder builder, Plan plan) {\n        if (plan == null) throw new IllegalArgumentException("26541 Night exposure plan is null");\n        apply(builder, plan.longExposureNs, plan.longIso, "long");\n    }\n\n    // Compatibility alias: callers that mean the reference cohort get the short plan.\n    public static void applyPlan(CaptureRequest.Builder builder, Plan plan) {\n        applyShortPlan(builder, plan);\n    }\n}\n''')

    write(root,'batch','''package com.particlesdevs.photoncamera.processing;\n\nimport android.hardware.camera2.CameraCharacteristics;\nimport android.hardware.camera2.CaptureRequest;\nimport android.hardware.camera2.TotalCaptureResult;\n\nimport com.particlesdevs.photoncamera.control.GyroBurst;\nimport com.particlesdevs.photoncamera.processing.parameters.IrisNightFrameSelector;\n\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * IRIS_26541_NIGHT_IMMUTABLE_12_PLUS_3_BATCH_OWNER\n *\n * One shutter-frozen, fresh-capture Night batch. SHORT/NORMAL frames own reference geometry;\n * SHADOW_LONG frames retain exact per-frame Camera2 metadata and may only add shadow evidence.\n * No Motion ZSL/ring/pre-shutter RAW, Photon static IMAGE_BUFFER, or live settings own this batch.\n */\npublic final class IrisNightBatch {\n    public final List<ImageFrame> frames;\n    public final List<GyroBurst> gyro;\n    public final Map<Long, Double> exposures;\n    public final Map<Long, TotalCaptureResult> results;\n    public final Map<Long, CaptureRequest> requests;\n    public final TotalCaptureResult referenceResult;\n    public final CaptureRequest referenceRequest;\n    public final CameraCharacteristics characteristics;\n    public final int imageFormat;\n    public final int rotation;\n    public final int frameBudget;\n    public final int requestedShortFrames;\n    public final int requestedLongFrames;\n    public final int shortFrameCount;\n    public final int longFrameCount;\n    public final int saveRaw;\n    public final boolean superResEnabled;\n    public final boolean aspect169;\n    public final boolean energySaving;\n    public final boolean watermarkEnabled;\n    public final boolean binning;\n    public final String cameraId;\n    public final com.particlesdevs.photoncamera.processing.processor.IrisMotionSettings.Snapshot irisSettings;\n\n    public IrisNightBatch(\n            List<ImageFrame> frames,\n            List<GyroBurst> gyro,\n            Map<Long, Double> exposures,\n            Map<Long, TotalCaptureResult> results,\n            Map<Long, CaptureRequest> requests,\n            CameraCharacteristics characteristics,\n            int imageFormat,\n            int rotation,\n            int frameBudget,\n            int saveRaw,\n            boolean superResEnabled,\n            boolean aspect169,\n            boolean energySaving,\n            boolean watermarkEnabled,\n            boolean binning,\n            String cameraId,\n            com.particlesdevs.photoncamera.processing.processor.IrisMotionSettings.Snapshot irisSettings) {\n        if (frames == null || frames.size() < 2)\n            throw new IllegalArgumentException("26541 NightBatch requires at least two exact RAW frames");\n        if (results == null || requests == null || characteristics == null)\n            throw new IllegalArgumentException("26541 NightBatch exact metadata/characteristics are required");\n        if (frameBudget < 2 || frameBudget > IrisNightFrameSelector.TOTAL_FRAMES)\n            throw new IllegalArgumentException("26541 NightBatch invalid actual frame budget=" + frameBudget);\n\n        ArrayList<ImageFrame> ordered = new ArrayList<>(frames);\n        ordered.sort(java.util.Comparator.comparingLong(ImageFrame::getTimestamp));\n        HashMap<Long, Double> expoCopy = new HashMap<>();\n        HashMap<Long, TotalCaptureResult> resultCopy = new HashMap<>();\n        HashMap<Long, CaptureRequest> requestCopy = new HashMap<>();\n        int shortCount = 0;\n        int longCount = 0;\n        ImageFrame reference = null;\n        for (ImageFrame frame : ordered) {\n            if (frame == null || !frame.motionV2PlaneLayoutValid)\n                throw new IllegalArgumentException("26541 NightBatch RAW layout missing");\n            TotalCaptureResult result = results.get(frame.timestamp);\n            CaptureRequest request = requests.get(frame.timestamp);\n            if (result == null || request == null)\n                throw new IllegalArgumentException("26541 NightBatch exact metadata missing timestamp=" + frame.timestamp);\n            Long resultTimestamp = result.get(android.hardware.camera2.CaptureResult.SENSOR_TIMESTAMP);\n            if (resultTimestamp == null || resultTimestamp.longValue() != frame.timestamp)\n                throw new IllegalArgumentException("26541 NightBatch timestamp mismatch image=" + frame.timestamp\n                        + " result=" + resultTimestamp);\n            if (frame.motionV2ActualExposureNs <= 0L || frame.motionV2ActualIso <= 0\n                    || !frame.motionV2NoiseProfileValid || !frame.motionV2BlackLevelValid\n                    || !frame.motionV2WhiteLevelValid)\n                throw new IllegalArgumentException("26541 NightBatch exact radiometric metadata missing timestamp=" + frame.timestamp);\n            if (frame.motionV2FrameRole == ImageFrame.MotionV2FrameRole.HIGHLIGHT_SHORT)\n                throw new IllegalArgumentException("26541 Night never admits Motion HIGHLIGHT_SHORT role");\n            if (frame.motionV2FrameRole == ImageFrame.MotionV2FrameRole.SHADOW_LONG) {\n                longCount++;\n            } else if (frame.motionV2FrameRole == ImageFrame.MotionV2FrameRole.NORMAL) {\n                shortCount++;\n                if (reference == null) reference = frame;\n            } else {\n                throw new IllegalArgumentException("26541 Night unknown frame role=" + frame.motionV2FrameRole);\n            }\n            expoCopy.put(frame.timestamp, frame.motionV2ExposureEnergy);\n            resultCopy.put(frame.timestamp, result);\n            requestCopy.put(frame.timestamp, request);\n        }\n        if (shortCount < 2 || reference == null)\n            throw new IllegalArgumentException("26541 Night requires at least two exact SHORT/reference frames; got=" + shortCount);\n        if (shortCount > IrisNightFrameSelector.SHORT_FRAMES || longCount > IrisNightFrameSelector.LONG_FRAMES)\n            throw new IllegalArgumentException("26541 Night role counts exceed 12+3 request: short=" + shortCount + " long=" + longCount);\n        final double referenceEnergy = reference.motionV2ExposureEnergy;\n        for (ImageFrame frame : ordered) {\n            if (frame.motionV2FrameRole == ImageFrame.MotionV2FrameRole.SHADOW_LONG\n                    && !(frame.motionV2ExposureEnergy > referenceEnergy))\n                throw new IllegalArgumentException("26541 Night SHADOW_LONG is not above SHORT reference energy");\n        }\n\n        this.frames = Collections.unmodifiableList(ordered);\n        this.gyro = Collections.unmodifiableList(new ArrayList<>(gyro == null ? Collections.emptyList() : gyro));\n        this.exposures = Collections.unmodifiableMap(expoCopy);\n        this.results = Collections.unmodifiableMap(resultCopy);\n        this.requests = Collections.unmodifiableMap(requestCopy);\n        this.referenceResult = resultCopy.get(reference.timestamp);\n        this.referenceRequest = requestCopy.get(reference.timestamp);\n        this.characteristics = characteristics;\n        this.imageFormat = imageFormat;\n        this.rotation = rotation;\n        this.frameBudget = frameBudget;\n        this.requestedShortFrames = IrisNightFrameSelector.SHORT_FRAMES;\n        this.requestedLongFrames = IrisNightFrameSelector.LONG_FRAMES;\n        this.shortFrameCount = shortCount;\n        this.longFrameCount = longCount;\n        this.saveRaw = saveRaw;\n        this.superResEnabled = superResEnabled;\n        this.aspect169 = aspect169;\n        this.energySaving = energySaving;\n        this.watermarkEnabled = watermarkEnabled;\n        this.binning = binning;\n        this.cameraId = cameraId == null ? "0" : cameraId;\n        if (irisSettings == null || irisSettings.customNoiseModelEnabled)\n            throw new IllegalArgumentException("26541 NightBatch requires exact-Camera2 Iris settings");\n        this.irisSettings = irisSettings;\n    }\n}\n''')

    # Night processor: choose first SHORT/NORMAL as base and preserve actual radiometric ratios.
    p=root/REL['processor']; s=p.read_text()
    s=once(s,
'''            final ArrayList<ImageFrame> images = new ArrayList<>(batch.frames);\n            images.sort(java.util.Comparator.comparingLong(ImageFrame::getTimestamp));\n            final ImageFrame base = images.get(0);\n''',
'''            final ArrayList<ImageFrame> images = new ArrayList<>(batch.frames);\n            images.sort(java.util.Comparator.comparingLong(ImageFrame::getTimestamp));\n            final ImageFrame base = images.stream()\n                    .filter(f -> f.motionV2FrameRole == ImageFrame.MotionV2FrameRole.NORMAL)\n                    .findFirst()\n                    .orElseThrow(() -> new IllegalStateException("26541 Night SHORT reference missing"));\n''','Night base selection')
    s=once(s,
'''                frame.number = i;\n                frame.pair = null;\n                frame.irisRelativeExposureMpy = 1.0f;\n''',
'''                frame.number = i;\n                frame.pair = null;\n                frame.irisRelativeExposureMpy = (float) (\n                        base.motionV2ExposureEnergy / Math.max(1.0e-12, frame.motionV2ExposureEnergy));\n                if (!Float.isFinite(frame.irisRelativeExposureMpy) || frame.irisRelativeExposureMpy <= 0.0f)\n                    throw new IllegalStateException("26541 Night relative exposure invalid index=" + i);\n''','Night relative exposure')
    s=once(s,
'''            Log.i(TAG, "IRIS_26540_NIGHT_DIRECT_PROCESS_ENTRY frames=" + images.size()\n                    + " frameBudget=" + batch.frameBudget\n                    + " exactReferenceTimestamp=" + ref\n                    + " staticImageBuffer=false defaultSaver=false hdrxRun=false"\n                    + " applyRes=false fillDynamic=false photonNoiseModeler=false"\n                    + " superRes=" + batch.superResEnabled);\n''',
'''            Log.i(TAG, "IRIS_26541_NIGHT_12_PLUS_3_DIRECT_PROCESS_ENTRY frames=" + images.size()\n                    + " shortActual=" + batch.shortFrameCount + " longActual=" + batch.longFrameCount\n                    + " shortRequested=" + batch.requestedShortFrames + " longRequested=" + batch.requestedLongFrames\n                    + " frameBudget=" + batch.frameBudget + " exactReferenceTimestamp=" + ref\n                    + " referenceRole=SHORT zsl=false motionRing=false preShutterRaw=false"\n                    + " staticImageBuffer=false defaultSaver=false hdrxRun=false"\n                    + " applyRes=false fillDynamic=false photonNoiseModeler=false"\n                    + " superRes=" + batch.superResEnabled);\n''','Night process log')
    s=once(s,
'''            exif.IMAGE_DESCRIPTION = p.toString()\n                    + "\\nIRIS_26540_NIGHT irisCaptureOwner=true exactTimestampMetadata=true"\n''',
'''            exif.IMAGE_DESCRIPTION = p.toString()\n                    + "\\nIRIS_26541_NIGHT_12_PLUS_3 irisCaptureOwner=true exactTimestampMetadata=true"\n                    + " shortFrames=" + batch.shortFrameCount + "/" + batch.requestedShortFrames\n                    + " longFrames=" + batch.longFrameCount + "/" + batch.requestedLongFrames\n                    + " referenceRole=SHORT zsl=false motionRing=false preShutterRaw=false"\n''','Night EXIF marker')
    p.write_text(s)

    # MGC bridge: Night main-list SHADOW_LONG roles + exact zero MGC/Pecan luma rollback.
    p=root/REL['bridge']; s=p.read_text()
    s=once(s,
'''            val mgcBase = inputImages.first()\n            val orderedPhysical = ArrayList<Pair<ImageFrame, RawBurstFrameRole>>()\n            inputImages.forEach { orderedPhysical += it to RawBurstFrameRole.NORMAL }\n            longFrame?.let { orderedPhysical += it to RawBurstFrameRole.SHADOW_LONG }\n            shortFrame?.let { orderedPhysical += it to RawBurstFrameRole.HIGHLIGHT_SHORT }\n''',
'''            val mgcBase = inputImages.firstOrNull { it.motionV2FrameRole == ImageFrame.MotionV2FrameRole.NORMAL }\n                ?: invalid("MGC SHORT/NORMAL base is absent")\n            val orderedPhysical = ArrayList<Pair<ImageFrame, RawBurstFrameRole>>()\n            inputImages.forEachIndexed { index, frame ->\n                val role = when (frame.motionV2FrameRole) {\n                    ImageFrame.MotionV2FrameRole.NORMAL -> RawBurstFrameRole.NORMAL\n                    ImageFrame.MotionV2FrameRole.SHADOW_LONG -> {\n                        requireParity(parameters.irisNightActive,\n                            "main-list SHADOW_LONG is Night-only index=$index")\n                        RawBurstFrameRole.SHADOW_LONG\n                    }\n                    ImageFrame.MotionV2FrameRole.HIGHLIGHT_SHORT ->\n                        invalid("main-list HIGHLIGHT_SHORT is forbidden; Motion Short keeps isolated slot ownership")\n                }\n                orderedPhysical += frame to role\n            }\n            longFrame?.let { orderedPhysical += it to RawBurstFrameRole.SHADOW_LONG }\n            shortFrame?.let { orderedPhysical += it to RawBurstFrameRole.HIGHLIGHT_SHORT }\n''','MGC role mapping')
    s=once(s,
'''            val requestedLumaScale = irisSettings.lumaDenoise.coerceIn(0f, 2f)\n            val noiseEquivalentSupport = stacked.normalStackedDngNoiseEquivalentSupport\n            requireParity(noiseEquivalentSupport.isFinite() && noiseEquivalentSupport >= 1f,\n                "missing/malformed noise-equivalent temporal support")\n            val userLumaScale = if (irisSettings.noiseReductionEnabled)\n                requestedLumaScale else 0f\n            val lumaScale = userLumaScale.coerceIn(0f, 1.5f)\n            val chromaScale = irisSettings.chromaDenoise\n''',
'''            val requestedLumaScale = irisSettings.lumaDenoise.coerceIn(0f, 2f)\n            val noiseEquivalentSupport = stacked.normalStackedDngNoiseEquivalentSupport\n            requireParity(noiseEquivalentSupport.isFinite() && noiseEquivalentSupport >= 1f,\n                "missing/malformed noise-equivalent temporal support")\n            /* IRIS_26541_RESTORE_26535_ZERO_MGC_LUMA\n             * The 26536+ low-light/mottle luma experiment did not improve the user's Motion\n             * samples. Restore the proven 26531/26535 full-resolution Pecan/MGC luma contract\n             * exactly to zero for Motion and Night. Chroma remains user-owned, and the separate\n             * >=8x SR temporal-luma weighting inside the reconstruction shader is untouched.\n             */\n            val userLumaScale = 0f\n            val lumaScale = 0f\n            val chromaScale = irisSettings.chromaDenoise\n''','zero MGC luma')
    s=once(s,
'''                "requestedLuma=$requestedLumaScale automaticLowLightLuma=0.0 " +\n                "userLuma=$userLumaScale effectiveMgcLuma=$lumaScale " +\n''',
'''                "requestedLuma=$requestedLumaScale automaticLowLightLuma=0.0 " +\n                "userLuma=$userLumaScale effectiveMgcLuma=$lumaScale " +\n                "zeroLumaRollback=IRIS_26541_RESTORE_26535_ZERO_MGC_LUMA " +\n''','luma log')
    p.write_text(s)

    # Strict, highlight-only opposed reconstruction. Non-clipped center returns byte-identical RGB.
    write(root,'highlight_java','''package com.particlesdevs.photoncamera.processing.opengl.postpipeline;\n\nimport android.graphics.Point;\nimport com.particlesdevs.photoncamera.processing.opengl.GLFormat;\nimport com.particlesdevs.photoncamera.processing.opengl.GLTexture;\nimport com.particlesdevs.photoncamera.processing.opengl.nodes.Node;\nimport com.particlesdevs.photoncamera.util.Log;\nimport java.nio.ByteBuffer;\nimport java.nio.ByteOrder;\nimport static android.opengl.GLES20.GL_CLAMP_TO_EDGE;\nimport static android.opengl.GLES20.GL_LINEAR;\n\n/**\n * IRIS_26541_HIGHLIGHT_OPPOSED_RECONSTRUCTION\n *\n * Complete the recent RawTherapee-inspired false-color work as a dedicated highlight operation,\n * not a general chroma filter. A non-near-clipped center is returned unchanged. Partially censored\n * highlights may borrow opposed-channel chroma only from reliable, unclipped, same-surface donor\n * pairs. Fully censored highlights may move toward the timestamp-owned Camera2 neutral axis while\n * preserving camera-linear luminance. No RCD/demosaic detour exists.\n */\npublic final class MotionV2HighlightChromaReliability extends Node {\n    public MotionV2HighlightChromaReliability() { super("", "MotionV2HighlightChromaReliability"); }\n    @Override public void Compile() {}\n\n    @Override public void Run() {\n        if (!(basePipeline.mParameters.motionV2Active || basePipeline.mParameters.irisNightActive))\n            throw new IllegalStateException("Highlight reconstruction outside Iris Spatial RGB");\n        float[] reliability = basePipeline.mParameters.motionV2SpatialReliability;\n        int rw = basePipeline.mParameters.motionV2SpatialReliabilityWidth;\n        int rh = basePipeline.mParameters.motionV2SpatialReliabilityHeight;\n        if (reliability == null || rw <= 0 || rh <= 0 || reliability.length != rw * rh)\n            throw new IllegalStateException("26541 missing native Spatial reliability map");\n        float[] neutral = basePipeline.mParameters.whitePoint;\n        if (neutral == null || neutral.length < 3\n                || !Float.isFinite(neutral[0]) || !Float.isFinite(neutral[1]) || !Float.isFinite(neutral[2])\n                || neutral[0] <= 0f || neutral[1] <= 0f || neutral[2] <= 0f)\n            throw new IllegalStateException("26541 missing timestamp-owned Camera2 neutral point");\n\n        ByteBuffer rb = ByteBuffer.allocateDirect(reliability.length * 4).order(ByteOrder.nativeOrder());\n        for (float v : reliability) rb.putFloat(Float.isFinite(v) ? Math.max(0.0f, Math.min(1.0f, v)) : 0.0f);\n        rb.position(0);\n        GLTexture reliabilityTex = new GLTexture(new Point(rw, rh),\n                new GLFormat(GLFormat.DataType.FLOAT_32, 1), rb, GL_LINEAR, GL_CLAMP_TO_EDGE);\n        try {\n            glProg.useAssetProgram("motionv2/highlight_chroma_reliability");\n            glProg.setTexture("InputBuffer", previousNode.WorkingTexture);\n            glProg.setTexture("ReliabilityMap", reliabilityTex);\n            glProg.setVar("CameraNeutral", new float[]{neutral[0], neutral[1], neutral[2]});\n            WorkingTexture = basePipeline.getMain();\n            glProg.drawBlocks(WorkingTexture);\n            glProg.closed = true;\n            Log.i(Name, "IRIS_26541_HIGHLIGHT_OPPOSED_RECONSTRUCTION"\n                    + " lumaLowerBoundPreserved=true centerNearClipRequired=true nonClipActivation=0"\n                    + " opposedDonorsUnclipped=true opposedDonorsReliable=true sameSurfacePairs=true edgeGate=true"\n                    + " fullCensorNeutral=Camera2_SENSOR_NEUTRAL_COLOR_POINT"\n                    + " maxOpposedAmount=0.78 fullCensorNeutralUpTo=1.0"\n                    + " nativeSpatialReliability=true rcd=false treeFoliageNonClipProtected=true"\n                    + " reliabilityMean=" + basePipeline.mParameters.motionV2SpatialReliabilityMean\n                    + " lowReliabilityFraction=" + basePipeline.mParameters.motionV2SpatialReliabilityLowFraction\n                    + " stage=beforeProfileColor");\n        } finally {\n            reliabilityTex.close();\n        }\n    }\n}\n''')

    write(root,'highlight_shader','''precision highp float;\nprecision highp sampler2D;\nuniform sampler2D InputBuffer;\nuniform sampler2D ReliabilityMap;\nuniform vec3 CameraNeutral;\nout vec3 Output;\n\nfloat lum(vec3 c){ return 0.25*c.r + 0.50*c.g + 0.25*c.b; }\nvec2 chr(vec3 c){ return vec2(c.r-c.b, c.g-0.5*(c.r+c.b)); }\nvec3 fromYChroma(float y,vec2 q){\n    return vec3(y - 0.5*q.y + 0.5*q.x, y + 0.5*q.y, y - 0.5*q.y - 0.5*q.x);\n}\nfloat peak3(vec3 c){ return max(c.r,max(c.g,c.b)); }\nfloat min3(vec3 c){ return min(c.r,min(c.g,c.b)); }\nfloat relAt(ivec2 p,ivec2 sz){\n    vec2 uv=(vec2(p)+vec2(0.5))/vec2(sz);\n    return clamp(texture(ReliabilityMap,uv).r,0.0,1.0);\n}\nfloat unclipped(vec3 c){ return 1.0-smoothstep(0.84,0.94,peak3(c)); }\n\n/* Opposed donors must both be real, unclipped, reliable observations on the same luminance surface. */\nvec3 opposedPair(ivec2 a,ivec2 b,ivec2 sz,float centerY,out float w){\n    vec3 ca=max(texelFetch(InputBuffer,a,0).rgb,vec3(0.0));\n    vec3 cb=max(texelFetch(InputBuffer,b,0).rgb,vec3(0.0));\n    float ya=lum(ca), yb=lum(cb);\n    float meanY=0.5*(ya+yb);\n    float surfaceTol=0.012 + 0.080*sqrt(max(meanY,0.0));\n    float pairSurface=1.0-smoothstep(surfaceTol,2.5*surfaceTol,abs(ya-yb));\n    float centerTol=0.018 + 0.110*sqrt(max(centerY,0.0));\n    float centerSurface=1.0-smoothstep(centerTol,2.5*centerTol,abs(meanY-centerY));\n    float reliable=smoothstep(0.55,0.82,min(relAt(a,sz),relAt(b,sz)));\n    w=unclipped(ca)*unclipped(cb)*pairSurface*centerSurface*reliable;\n    return 0.5*(ca+cb);\n}\n\nvoid main(){\n    ivec2 xy=ivec2(gl_FragCoord.xy);\n    ivec2 sz=textureSize(InputBuffer,0);\n    vec3 c=max(texelFetch(InputBuffer,xy,0).rgb,vec3(0.0));\n    float y0=lum(c);\n\n    /* Hard 26535-style authority boundary: weak reliability alone never changes ordinary edges. */\n    float centerClipGate=smoothstep(0.88,0.985,peak3(c));\n    if(centerClipGate<=0.0){ Output=c; return; }\n\n    ivec2 xm=ivec2(0);\n    ivec2 xp=sz-ivec2(1);\n    ivec2 l=clamp(xy+ivec2(-1,0),xm,xp), r=clamp(xy+ivec2(1,0),xm,xp);\n    ivec2 d=clamp(xy+ivec2(0,-1),xm,xp), u=clamp(xy+ivec2(0,1),xm,xp);\n    ivec2 dl=clamp(xy+ivec2(-1,-1),xm,xp), ur=clamp(xy+ivec2(1,1),xm,xp);\n    ivec2 ul=clamp(xy+ivec2(-1,1),xm,xp), dr=clamp(xy+ivec2(1,-1),xm,xp);\n\n    float yl=lum(max(texelFetch(InputBuffer,l,0).rgb,vec3(0.0)));\n    float yr=lum(max(texelFetch(InputBuffer,r,0).rgb,vec3(0.0)));\n    float yd=lum(max(texelFetch(InputBuffer,d,0).rgb,vec3(0.0)));\n    float yu=lum(max(texelFetch(InputBuffer,u,0).rgb,vec3(0.0)));\n    float edge=max(max(abs(yl-y0),abs(yr-y0)),max(abs(yu-y0),abs(yd-y0)));\n    float edgeScale=0.012 + 0.060*sqrt(max(y0,0.0));\n    float edgeGate=smoothstep(edgeScale,3.2*edgeScale,edge);\n\n    float w0,w1,w2,w3;\n    vec3 p0=opposedPair(l,r,sz,y0,w0);\n    vec3 p1=opposedPair(d,u,sz,y0,w1);\n    vec3 p2=opposedPair(dl,ur,sz,y0,w2);\n    vec3 p3=opposedPair(ul,dr,sz,y0,w3);\n    float wsum=w0+w1+w2+w3;\n    vec2 qTarget=chr(c);\n    if(wsum>1.0e-6){\n        qTarget=(w0*chr(p0)+w1*chr(p1)+w2*chr(p2)+w3*chr(p3))/wsum;\n    }\n    float donorConfidence=clamp(wsum/2.0,0.0,1.0);\n    vec2 q0=chr(c);\n    float chromaDelta=length(q0-qTarget);\n    float chromaScale=0.006 + 0.030*sqrt(max(y0,0.0));\n    float outlierGate=smoothstep(chromaScale,3.5*chromaScale,chromaDelta);\n    float opposedAmount=0.78*centerClipGate*edgeGate*outlierGate*donorConfidence;\n    vec3 opposed=fromYChroma(y0,qTarget);\n    vec3 repaired=mix(c,opposed,clamp(opposedAmount,0.0,0.78));\n\n    /* IRIS_26541_FULL_CENSOR_CAMERA_NEUTRAL_FALLBACK\n     * When all camera-linear channels are censored and opposed donors are insufficient, chroma is\n     * unknowable. Move only toward the exact Camera2 neutral axis, never toward an invented hue.\n     */\n    float fullCensorGate=smoothstep(0.94,0.995,min3(c));\n    float neutralNeed=fullCensorGate*(1.0-donorConfidence);\n    vec3 neutralDir=max(CameraNeutral,vec3(1.0e-6));\n    /* A fully clipped RGB triplet is a lower bound, not an exact color. Scale the camera-neutral\n     * direction UP until it is no darker than every censored center channel. */\n    float neutralScale=max(c.r/neutralDir.r,max(c.g/neutralDir.g,c.b/neutralDir.b));\n    vec3 neutralAxis=neutralDir*max(neutralScale,1.0e-6);\n    repaired=mix(repaired,neutralAxis,clamp(neutralNeed,0.0,1.0));\n\n    /* A censored center channel may never be reconstructed below its observed lower bound. */\n    if(c.r>=0.985) repaired.r=max(repaired.r,c.r);\n    if(c.g>=0.985) repaired.g=max(repaired.g,c.g);\n    if(c.b>=0.985) repaired.b=max(repaired.b,c.b);\n    repaired=max(repaired,vec3(0.0));\n    float repairedY=lum(repaired);\n    if(repairedY<y0) repaired+=vec3(y0-repairedY);\n    Output=repaired;\n}\n''')

    # CaptureController: exact request tags drive per-frame role from timestamp-matched request.
    p=root/REL['capture']; s=p.read_text()
    s=once(s,
'''    private int mIrisNight26540Rotation = 0;\n''',
'''    private int mIrisNight26540Rotation = 0;\n    private static final String IRIS_26541_NIGHT_SHORT_TAG = "IRIS_26541_NIGHT_SHORT";\n    private static final String IRIS_26541_NIGHT_LONG_TAG = "IRIS_26541_NIGHT_LONG";\n''','Night request tags')
    s=once(s,
'''    private static void populateIrisNight26540FrameMetadata(@NonNull ImageFrame frame,\n            @NonNull TotalCaptureResult result, @NonNull CameraCharacteristics characteristics) {\n''',
'''    private static void populateIrisNight26540FrameMetadata(@NonNull ImageFrame frame,\n            @NonNull TotalCaptureResult result, @NonNull CaptureRequest request,\n            @NonNull CameraCharacteristics characteristics) {\n''','Night metadata signature')
    s=once(s,
'''        frame.motionV2FrameRole = ImageFrame.MotionV2FrameRole.NORMAL;\n        frame.motionV2ShortHighlightFrame = false;\n''',
'''        Object iris26541RoleTag = request.getTag();\n        if (IRIS_26541_NIGHT_SHORT_TAG.equals(iris26541RoleTag)) {\n            frame.motionV2FrameRole = ImageFrame.MotionV2FrameRole.NORMAL;\n        } else if (IRIS_26541_NIGHT_LONG_TAG.equals(iris26541RoleTag)) {\n            frame.motionV2FrameRole = ImageFrame.MotionV2FrameRole.SHADOW_LONG;\n        } else {\n            throw new IllegalStateException("26541 Night exact request is missing SHORT/LONG role tag: "\n                    + iris26541RoleTag);\n        }\n        frame.motionV2ShortHighlightFrame = false;\n''','Night metadata role')
    s=once(s,
'''                    populateIrisNight26540FrameMetadata(frame, exact, mIrisNight26540Characteristics);\n''',
'''                    populateIrisNight26540FrameMetadata(frame, exact, exactRequest,\n                            mIrisNight26540Characteristics);\n''','Night metadata call')
    s=once(s,
'''        Log.i(TAG, "IRIS_26540_NIGHT_BATCH_SEALED frames=" + batch.frames.size()\n                + " exactResults=" + batch.results.size()\n                + " staticImageBuffer=false defaultSaver=false hdrxRun=false");\n''',
'''        Log.i(TAG, "IRIS_26541_NIGHT_BATCH_SEALED frames=" + batch.frames.size()\n                + " shortActual=" + batch.shortFrameCount + " longActual=" + batch.longFrameCount\n                + " shortRequested=" + batch.requestedShortFrames + " longRequested=" + batch.requestedLongFrames\n                + " exactResults=" + batch.results.size()\n                + " zsl=false motionRing=false preShutterRaw=false"\n                + " staticImageBuffer=false defaultSaver=false hdrxRun=false");\n''','Night batch log')
    s=once(s,
'''            final IrisNightExposureSelector.Plan iris26540NightPlan =\n                    iris26533CaptureMode == CameraMode.NIGHT\n                            ? IrisNightExposureSelector.freezePlan(\n                                    this, mCameraCharacteristics,\n                                    iris26540ExposureCompensation,\n                                    PhotonCamera.getGyro() != null && PhotonCamera.getGyro().getTripod(),\n                                    PhotonCamera.getGyro() == null ? 0 : PhotonCamera.getGyro().getFilteredShakiness(),\n                                    mPreviewCaptureResult)\n                            : null;\n''',
'''            final IrisNightExposureSelector.Plan iris26540NightPlan =\n                    iris26533CaptureMode == CameraMode.NIGHT\n                            ? IrisNightExposureSelector.freezePlan(\n                                    this, mCameraCharacteristics,\n                                    iris26540ExposureCompensation,\n                                    PhotonCamera.getGyro() != null && PhotonCamera.getGyro().getTripod(),\n                                    PhotonCamera.getGyro() == null ? 0 : PhotonCamera.getGyro().getFilteredShakiness(),\n                                    mPreviewCaptureResult)\n                            : null;\n            if (iris26533CaptureMode == CameraMode.NIGHT) {\n                if (isZslMode()) throw new IllegalStateException("26541 Night must never enter Motion ZSL");\n                Log.i(TAG, "IRIS_26541_NIGHT_FRESH_CAPTURE_CONTRACT"\n                        + " zsl=false motionRing=false preShutterRaw=false shutterTriggeredFreshRaw=true"\n                        + " shortRequested=" + IrisNightFrameSelector.SHORT_FRAMES\n                        + " longRequested=" + IrisNightFrameSelector.LONG_FRAMES);\n            }\n''','Night fresh contract')
    s=once(s,
'''                for (int i = 0; i < frameCount; i++) {\n                    if (iris26533CaptureMode == CameraMode.NIGHT) {\n                        IrisNightExposureSelector.applyPlan(captureBuilder, iris26540NightPlan);\n                    } else {\n                        IsoExpoSelector.setExpo(captureBuilder, i, this);\n                    }\n                    times[i] = iris26533CaptureMode == CameraMode.NIGHT\n                            ? iris26540NightPlan.exposureNs\n                            : IsoExpoSelector.lastSelectedExposure;\n                    captures.add(captureBuilder.build());\n                    mCaptureRequest = captureBuilder.build();\n                }\n''',
'''                for (int i = 0; i < frameCount; i++) {\n                    if (iris26533CaptureMode == CameraMode.NIGHT) {\n                        if (frameCount != IrisNightFrameSelector.TOTAL_FRAMES)\n                            throw new IllegalStateException("26541 Night request count is not 12+3: " + frameCount);\n                        if (i < IrisNightFrameSelector.SHORT_FRAMES) {\n                            IrisNightExposureSelector.applyShortPlan(captureBuilder, iris26540NightPlan);\n                            captureBuilder.setTag(IRIS_26541_NIGHT_SHORT_TAG);\n                            times[i] = iris26540NightPlan.shortExposureNs;\n                        } else {\n                            IrisNightExposureSelector.applyLongPlan(captureBuilder, iris26540NightPlan);\n                            captureBuilder.setTag(IRIS_26541_NIGHT_LONG_TAG);\n                            times[i] = iris26540NightPlan.longExposureNs;\n                        }\n                    } else {\n                        IsoExpoSelector.setExpo(captureBuilder, i, this);\n                        times[i] = IsoExpoSelector.lastSelectedExposure;\n                    }\n                    CaptureRequest built = captureBuilder.build();\n                    captures.add(built);\n                    mCaptureRequest = built;\n                }\n                if (iris26533CaptureMode == CameraMode.NIGHT) {\n                    Log.i(TAG, "IRIS_26541_NIGHT_12_PLUS_3_REQUESTS"\n                            + " short=12 long=3 total=" + captures.size()\n                            + " shortNs=" + iris26540NightPlan.shortExposureNs\n                            + " longNs=" + iris26540NightPlan.longExposureNs\n                            + " shortIso=" + iris26540NightPlan.shortIso\n                            + " longIso=" + iris26540NightPlan.longIso\n                            + " longToShortEnergy=" + iris26540NightPlan.longToShortEnergyRatio\n                            + " zsl=false");\n                    // Built requests retain immutable tags; clear the mutable builder afterwards.\n                    captureBuilder.setTag(null);\n                }\n''','Night 12+3 request loop')
    p.write_text(s)

    # Version remains exact 26540 through source safety proof. The guarded build script owns
    # the 0.9726541 / 26541 bump only after PRE-BUILD SAFETY PROOF PASSED.
    if (root/REL['version']).read_text() != v:
        raise RuntimeError('26541 transform modified version before safety proof')


def self_test():
    base=Path('/mnt/data/iris26541_work/base')
    if not base.exists():
        print('SELFTEST SKIP: exact base not present'); return
    with tempfile.TemporaryDirectory() as td:
        r=Path(td); shutil.copytree(base/'app',r/'app')
        transform(r)
        assert 'VERSION_BUILD=26540' in (r/REL['version']).read_text()
        assert 'lowReliabilityGate' not in (r/REL['highlight_shader']).read_text()
        assert 'centerClipGate<=0.0' in (r/REL['highlight_shader']).read_text()
        assert 'val lumaScale = 0f' in (r/REL['bridge']).read_text()
        assert 'LONG_FRAMES = 3' in (r/REL['selector']).read_text()
    print('PASS: 26541 transform self-test')

if __name__=='__main__':
    ap=argparse.ArgumentParser(); ap.add_argument('root',nargs='?'); ap.add_argument('--self-test',action='store_true')
    a=ap.parse_args()
    if a.self_test: self_test()
    else:
        if not a.root: ap.error('root required')
        transform(Path(a.root)); print('PASS: 26541 transform applied')
